#!/bin/bash
# validate-test-doubles.sh <file-or-directory>...
# Text-pattern checks on test doubles. Pass the module root so that directives
# and generated files can be matched. vendor/, node_modules/, .git are skipped.
# Exit 0 = no FAIL (WARNs need judgement), 1 = at least one FAIL,
# 2 = usage error, missing path or nothing to check.
set -uo pipefail
if [ "$#" -eq 0 ]; then
  echo "usage: validate-test-doubles.sh <file-or-directory>..." >&2
  exit 2
fi
exec python3 -I - "$@" <<'PY'
import os, re, sys

SKIP = {".git", ".venv", "venv", "node_modules", "vendor", "__pycache__", "testdata"}
MARKER = re.compile(r"^// Code generated .* DO NOT EDIT\.$", re.M)
MOCKERY = {".mockery.yaml", ".mockery.yml"}

files = []
for arg in sys.argv[1:]:
    if os.path.isfile(arg):
        files.append(arg)
    elif os.path.isdir(arg):
        for base, dirs, names in os.walk(arg):
            dirs[:] = sorted(d for d in dirs if d not in SKIP)
            files += [os.path.join(base, n) for n in sorted(names)
                      if n.endswith((".go", ".py", ".sh", ".yaml", ".yml")) or n in MOCKERY or n == "Makefile"]
    else:
        print(f"ERROR: no such path: {arg}")
        sys.exit(2)
if not files:
    print("ERROR: no files to check; nothing was checked")
    sys.exit(2)

texts = {}
for path in files:
    try:
        texts[path] = open(path, encoding="utf-8", errors="replace").read()
    except OSError as exc:
        print(f"ERROR: cannot read {path}: {exc}")
        sys.exit(2)

fails = warns = 0
def report(level, rule, path, line, message):
    global fails, warns
    fails += level == "FAIL"
    warns += level == "WARN"
    print(f"{level} {rule} {path}:{line}: {message}")

# Outputs named by moq directives, as absolute paths.
outputs = set()
for path, text in texts.items():
    for line in text.splitlines():
        if line.startswith("//go:generate") and re.search(r"\bmoq\b", line):
            out = re.search(r"\s-out[ =](\S+)", line)
            if out:
                outputs.add(os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(path)), out.group(1))))

# (level, rule, extension, pattern, message)
CHECKS = [
    ("FAIL", "M5", ".go", r'"(go\.uber\.org/mock|github\.com/golang/mock)/', "gomock; generate with moq"),
    ("FAIL", "M5", ".go", r'"github\.com/stretchr/testify/mock"', "testify mock; generate with moq"),
    ("FAIL", "M5", ".go", r"^//go:generate\b.*\b(mockgen|mockery)\b", "other generator; use moq"),
    ("FAIL", "M5", "Makefile", r"^\t.*\b(mockgen|mockery)\b", "other generator; use moq"),
    ("FAIL", "M5", None, r"matryer/moq(/v\d+)?@latest", "unpinned moq; pin a version"),
    ("WARN", "M5", ".go", r"^//go:generate\b.*\bmoq\b.*\s-stub\b",
     "-stub: an unexpected call returns zero values instead of failing"),
    ("WARN", "M5", ".go", r"^//go:generate\b.*\bmoq\b.*\s-skip-ensure\b",
     "-skip-ensure: keep the interface check"),
    ("FAIL", "M2", ".go", r"(?i)\b\w*repo(?!rt)(sitory)?\w*\.\w+Calls\(\)",
     "call assertion on a repository; assert the resulting state"),
    ("FAIL", "M2", ".py", r"(?i)\b\w*repo(?!rt)(sitory)?\w*(\.\w+)*\.(assert_(not_)?(called|awaited)\w*|assert_(has|any)_\w+|call_count|await_count|call_args\w*)\b",
     "call assertion on a repository; assert the resulting state"),
    ("WARN", "M1", ".go", r"^//go:generate\b.*\bmoq\b.*(pgx|franz-go|go-redis|aws-sdk)",
     "doubling a library type; define a port of your own"),
]

for path, text in texts.items():
    name = os.path.basename(path)
    ext = "Makefile" if name == "Makefile" else os.path.splitext(name)[1]
    if name in MOCKERY:
        report("FAIL", "M5", path, 1, "mockery configuration; generate with moq")
        continue
    if ext in ("Makefile", ".sh", ".yaml", ".yml") and "_moq" not in text:
        for number, line in enumerate(text.splitlines(), 1):
            if not line.strip().startswith("#") and re.search(r"_mock\\?\.go", line):
                report("FAIL", "M6", path, number, "filter matches only _mock.go; correct it to _moq.go")
    generated = bool(MARKER.search(text))
    parts = os.path.abspath(path).replace("\\", "/").split("/")
    is_moq = name.endswith(("_moq.go", "_moq_test.go"))
    if is_moq:
        if not generated:
            report("WARN", "M6", path, 1, "optional check (unverified): no '// Code generated ... "
                   "DO NOT EDIT.' line; confirm moq wrote this file")
        if os.path.abspath(path) not in outputs:
            report("FAIL", "M5", path, 1, "no moq go:generate directive writes this file; it will go stale "
                   "(pass the module root)")
    elif ext == ".go" and generated and re.search(r"Code generated by moq\b", text):
        report("WARN", "M5", path, 1, "optional check (unverified header): moq output not named <port>_moq.go")
    if generated and "fakes" in parts[:-1]:
        report("FAIL", "M6", path, 1, "generated marker in a fakes folder; a hand-written fake is counted")
    # Generated files are the generator's output: no line checks.
    if is_moq and os.path.abspath(path) in outputs:
        continue
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        comment = (stripped.startswith("#") and ext != "Makefile") or (
            stripped.startswith("//") and not stripped.startswith("//go:generate"))
        if comment:
            continue
        for level, rule, only, pattern, message in CHECKS:
            if only and only != ext:
                continue
            if re.search(pattern, line):
                report(level, rule, path, number, message)

# Every hand-written Go fake needs a compile-time interface assertion in its package.
packages = {}
for path, text in texts.items():
    if path.endswith(".go"):
        packages.setdefault(os.path.dirname(os.path.abspath(path)), []).append((path, text))
for directory, members in packages.items():
    joined = "\n".join(t for _, t in members)
    asserted = "\n".join(re.findall(r"^[ \t]*(?:var[ \t]+)?_[ \t]+[\w.\[\]]+[ \t]*=.*$", joined, re.M))
    for path, text in members:
        # In a fakes folder every exported struct is a fake; elsewhere, by name.
        in_fakes = os.path.basename(directory) == "fakes" and not path.endswith("_test.go")
        pattern = r"^type\s+([A-Z]\w*)\s+struct\b" if in_fakes else r"^type\s+([Ff]ake\w*)\s+struct\b"
        for found in re.finditer(pattern, text, re.M):
            fake = found.group(1)
            if not re.search(rf"\b{fake}\b", asserted):
                report("FAIL", "FAKE", path, text[:found.start()].count("\n") + 1,
                       f"{fake} has no compile-time assertion: var _ Port = (*{fake})(nil)")

print(f"checked {len(files)} file(s): {fails} FAIL, {warns} WARN")
sys.exit(1 if fails else 0)
PY
